import React, { useState, useEffect } from "react";
import {
  HomeIcon,
  UserIcon,
  ChatBubbleLeftIcon,
  ClipboardDocumentListIcon,
  MagnifyingGlassIcon,
  WalletIcon,
  ReceiptRefundIcon,
  ChatBubbleOvalLeftIcon,
  ArrowRightOnRectangleIcon,
  BellIcon,
  Bars3Icon,
  XMarkIcon,
  BookmarkIcon,
  CameraIcon,
  CheckCircleIcon,
  XCircleIcon,
  ClockIcon
} from "@heroicons/react/24/outline";
import { useNavigate } from 'react-router-dom';
import api from '../../../services/api'; 

export default function Profile() {
  const navigate = useNavigate();
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [userData, setUserData] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [editedData, setEditedData] = useState({});

  useEffect(() => {
  const storedUser = JSON.parse(localStorage.getItem('user'));
  setUserData(storedUser);
}, []);

  useEffect(() => {
  const fetchUserData = async () => {
    try {
      const storedUser = localStorage.getItem('user');
      if (storedUser) {
        const user = JSON.parse(storedUser);
        console.log('Stored user ID:', user.id); // Debug
        
        const response = await api.get(`/auth/user/${user.id}`);
        console.log('API Response:', response.data); // Debug
        
        const freshUserData = response.data;
        setUserData(freshUserData);
        localStorage.setItem('user', JSON.stringify(freshUserData));
      }
    } catch (error) {
      console.error('Error fetching user data:', error);
    }
  };

  fetchUserData();
}, []);

  useEffect(() => {
  if (userData) {
    setEditedData({
      full_name: userData.full_name || '',
      course: userData.course || '',
      year: userData.year || ''
    });
  }
}, [userData]);

  const handleEdit = () => {
    setIsEditing(true);
  };

  const handleSave = async () => {
    try {
      const response = await api.put(`/auth/update-profile/${userData.id}`, {
        full_name: editedData.full_name,
        course: editedData.course,
        year: editedData.year
      });

      const updatedUser = response.data.user;
      
      // Update both state and localStorage
      setUserData(updatedUser);
      localStorage.setItem('user', JSON.stringify(updatedUser));
      
      setIsEditing(false);
    } catch (error) {
      console.error('Error updating profile:', error);
    }
  };

  const handleChange = (e) => {
    setEditedData({
      ...editedData,
      [e.target.name]: e.target.value
    });
  };

  // Add to all components
const role = userData?.role?.toLowerCase() || '';

const navItems = (() => {
  if (role === 'learner') {
    return [
      { name: "Home", icon: <HomeIcon className="h-5 w-5" />, path: "/dashboard" },
      { name: "Profile", icon: <UserIcon className="h-5 w-5" />, path: "/profile" },
      { name: "Messages", icon: <ChatBubbleLeftIcon className="h-5 w-5" />, path: "/messages" },
      { name: "Find Services", icon: <MagnifyingGlassIcon className="h-5 w-5" />, path: "/find-services" },
      { name: "Saved", icon: <BookmarkIcon className="h-5 w-5" />, path: "/saved" },
      { name: "Wallet", icon: <WalletIcon className="h-5 w-5" />, path: "/wallet" },
      { name: "Transactions", icon: <ReceiptRefundIcon className="h-5 w-5" />, path: "/transactions" },
      { name: "Past Feedbacks", icon: <ChatBubbleOvalLeftIcon className="h-5 w-5" />, path: "/view-past-feedback" },
      { name: "Log Out", icon: <ArrowRightOnRectangleIcon className="h-5 w-5" />, path: "/" },
    ];
  }

  if (role === 'tutor') {
    return [
      { name: "Home", icon: <HomeIcon className="h-5 w-5" />, path: "/dashboard" },
      { name: "Profile", icon: <UserIcon className="h-5 w-5" />, path: "/profile" },
      { name: "Messages", icon: <ChatBubbleLeftIcon className="h-5 w-5" />, path: "/messages" },
      { name: "My Services", icon: <ClipboardDocumentListIcon className="h-5 w-5" />, path: "/my-services" },
      { name: "Wallet", icon: <WalletIcon className="h-5 w-5" />, path: "/wallet" },
      { name: "Transactions", icon: <ReceiptRefundIcon className="h-5 w-5" />, path: "/transactions" },
      { name: "Past Feedbacks", icon: <ChatBubbleOvalLeftIcon className="h-5 w-5" />, path: "/view-past-feedback" },
      { name: "Log Out", icon: <ArrowRightOnRectangleIcon className="h-5 w-5" />, path: "/" },
    ];
  }

  return [
    { name: "Home", icon: <HomeIcon className="h-5 w-5" />, path: "/dashboard" },
    { name: "Profile", icon: <UserIcon className="h-5 w-5" />, path: "/profile" },
    { name: "Messages", icon: <ChatBubbleLeftIcon className="h-5 w-5" />, path: "/messages" },
    { name: "My Services", icon: <ClipboardDocumentListIcon className="h-5 w-5" />, path: "/my-services" },
    { name: "Find Services", icon: <MagnifyingGlassIcon className="h-5 w-5" />, path: "/find-services" },
    { name: "Saved", icon: <BookmarkIcon className="h-5 w-5" />, path: "/saved" },
    { name: "Wallet", icon: <WalletIcon className="h-5 w-5" />, path: "/wallet" },
    { name: "Transactions", icon: <ReceiptRefundIcon className="h-5 w-5" />, path: "/transactions" },
    { name: "Past Feedbacks", icon: <ChatBubbleOvalLeftIcon className="h-5 w-5" />, path: "/view-past-feedback" },
    { name: "Log Out", icon: <ArrowRightOnRectangleIcon className="h-5 w-5" />, path: "/" },
  ];
})();

  // Function to render verification status
  const renderVerificationStatus = () => {
    console.log('User Data:', userData); // Debug log
    
    if (userData?.verification_status === 'approved') {
      return (
        <div className="flex items-center gap-2 border rounded-lg px-3 py-2 bg-green-50 border-green-200">
          <CheckCircleIcon className="h-5 w-5 text-green-500" />
          <span className="text-sm text-green-700 font-medium">Account Verified - Your account has been fully verified</span>
        </div>
      );
    } else if (userData?.verification_status === 'rejected') {
      return (
        <div className="flex items-center gap-2 border rounded-lg px-3 py-2 bg-red-50 border-red-200">
          <XCircleIcon className="h-5 w-5 text-red-500" />
          <span className="text-sm text-red-700 font-medium">Verification Rejected - Please contact support</span>
        </div>
      );
    }
    
    return (
      <div className="flex items-center gap-2 border rounded-lg px-3 py-2 bg-yellow-50 border-yellow-200">
        <ClockIcon className="h-5 w-5 text-yellow-500" />
        <span className="text-sm text-yellow-700 font-medium">Verification Pending - Your account is awaiting verification</span>
      </div>
    );
  };

  const renderFormInputs = () => (
  <div className="p-4 sm:p-6 space-y-4">
    <div>
      <label className="text-gray-600 text-sm">Full Name</label>
      <input
        type="text"
        name="full_name"
        value={editedData.full_name || ''}
        onChange={handleChange}
        readOnly={!isEditing}
        className={`w-full border rounded-lg px-3 py-2 mt-1 text-sm ${
          isEditing ? 'bg-white' : 'bg-gray-50'
        }`}
      />
    </div>

    {/* School Email */}
    <div>
      <label className="text-gray-600 text-sm">School Email</label>
      <div className="flex items-center border rounded-lg px-3 py-2 mt-1 justify-between bg-gray-50">
        <span className="text-sm">{userData?.email || ''}</span>
      </div>
      <p className="text-xs text-gray-500 mt-1"></p>
    </div>

    {/* Course */}
    <div>
      <label className="text-gray-600 text-sm">Course</label>
      <input
        type="text"
        name="course"
        value={editedData.course || ''}
        onChange={handleChange}
        readOnly={!isEditing}
        className={`w-full border rounded-lg px-3 py-2 mt-1 text-sm ${
          isEditing ? 'bg-white' : 'bg-gray-50'
        }`}
      />
    </div>

    {/* Year Level */}
    <div>
      <label className="text-gray-600 text-sm">Year Level</label>
      <input
        type="text"
        name="year"
        value={editedData.year || ''}
        onChange={handleChange}
        readOnly={!isEditing}
        className={`w-full border rounded-lg px-3 py-2 mt-1 text-sm ${
          isEditing ? 'bg-white' : 'bg-gray-50'
        }`}
      />
    </div>

    {/* Role */}
    <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between pt-2 gap-2">
      <span className="text-gray-700 font-medium text-sm">Role: {userData?.role || 'User'}</span>
      <button className="text-blue-500 text-xs sm:text-sm hover:text-blue-600 transition-colors">Request Change</button>
    </div>

    {/* Account Verification Status */}
    {renderVerificationStatus()}

    {/* Action Buttons */}
    {isEditing && (
      <div className="flex flex-col sm:flex-row justify-end gap-2 sm:gap-3">
        <button
          onClick={() => setIsEditing(false)}
          className="px-4 py-2 border rounded-lg hover:bg-gray-50 text-sm transition-colors"
        >
          Cancel
        </button>
        <button
          onClick={handleSave}
          className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 text-sm transition-colors"
        >
          Save Changes
        </button>
      </div>
    )}
  </div>
);

  return (
  <div className="min-h-screen bg-gradient-to-br from-blue-50 to-white flex">
    {/* Sidebar */}
    <div className="w-60 bg-white shadow-lg">
      {/* sidebar content */}
    </div>

    {/* Main content */}
    <div className="flex-1 p-6">
      <div className="max-w-2xl mx-auto">
        <div className="bg-white rounded-xl shadow-lg overflow-hidden">
          
          {/* Profile Header */}
          <div className="bg-gradient-to-r from-blue-600 to-indigo-600 px-6 py-12 flex flex-col items-center">
            <div className="relative">
              <div className="w-24 h-24 bg-gray-200 rounded-full flex items-center justify-center overflow-hidden border-4 border-white shadow-lg">
                {userData?.profileImage ? (
                  <img src={userData.profileImage} alt="Profile" className="w-full h-full object-cover" />
                ) : (
                  <svg className="w-12 h-12 text-gray-400" fill="currentColor" viewBox="0 0 24 24">
                    <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" />
                  </svg>
                )}
              </div>
              <button className="absolute bottom-0 right-0 bg-blue-500 p-2 rounded-full text-white hover:bg-blue-600">
                <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M19 13h-6v6h-2v-6H5v-2h6V5h2v6h6v2z" />
                </svg>
              </button>
            </div>
            <h2 className="text-2xl font-bold text-white mt-4">{userData?.full_name || 'User'}</h2>
            <p className="text-blue-100 mt-1">{userData?.email}</p>
          </div>

          {/* Profile Content */}
          <div className="p-6 space-y-4">
            {/* Full Name */}
            <div>
              <label className="text-gray-600 text-sm font-medium">Full Name</label>
              <p className="text-gray-800 font-semibold mt-1">{userData?.full_name || 'N/A'}</p>
            </div>

            {/* Email */}
            <div>
              <label className="text-gray-600 text-sm font-medium">School Email</label>
              <div className="flex items-center justify-between mt-1">
                <p className="text-gray-800">{userData?.email || 'N/A'}</p>
                <span className="text-xs text-green-600 font-medium">Verified</span>
              </div>
            </div>

            {/* Course */}
            <div>
              <label className="text-gray-600 text-sm font-medium">Course</label>
              <p className="text-gray-800 mt-1">{userData?.course || 'Not specified'}</p>
            </div>

            {/* Year Level */}
            <div>
              <label className="text-gray-600 text-sm font-medium">Year Level</label>
              <p className="text-gray-800 mt-1">{userData?.year || 'Not specified'}</p>
            </div>

            {/* Role */}
            <div className="flex items-center justify-between pt-2">
              <div>
                <label className="text-gray-600 text-sm font-medium">Role</label>
                <p className="text-gray-800 mt-1 font-semibold">{userData?.role || 'User'}</p>
              </div>
              <button className="text-blue-500 text-sm hover:text-blue-600">Request Change</button>
            </div>

            {/* Verification Status */}
            <div className="pt-4">
              {renderVerificationStatus()}
            </div>

            {/* Edit Button */}
            <button className="w-full mt-6 bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700 font-medium transition-colors">
              Edit Profile
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
);
}
